package com.privatezero.stadiumpad;
import java.net.*;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.cert.*;import javax.net.ssl.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import javax.crypto.SecretKey;import android.content.Context;import android.content.SharedPreferences;import android.security.keystore.*;import android.net.*;import org.json.*;

/** Pinned TLS relay; pairing is encrypted with an app-only Android Keystore key. */
final class PedalBridge {
 static void require(boolean b,String error)throws Exception{if(!b)throw new IOException(error);}
 static String hash(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 static final class Pair {
  final String host,pin,token;final int port;
  Pair(String link)throws Exception {URI u=new URI(link.trim());require("pedalbridge".equals(u.getScheme())&&"pair".equals(u.getHost()),"Paste the pairing link shown by PedalBridge");Map<String,String> m=new HashMap<>();String query=u.getRawQuery();require(query!=null,"Incomplete pairing link");for(String item:query.split("&")){String[] v=item.split("=",2);require(v.length==2,"Incomplete pairing link");String k=URLDecoder.decode(v[0],"UTF-8");require(!m.containsKey(k),"Duplicate pairing field");m.put(k,URLDecoder.decode(v[1],"UTF-8"));}host=m.get("host");pin=m.get("pin");token=m.get("token");port=Integer.parseInt(m.get("port"));require(host!=null&&host.length()<=253&&host.matches("[A-Za-z0-9.:-]+")&&pin!=null&&pin.matches("[a-f0-9]{64}")&&token!=null&&token.matches("[A-Za-z0-9_-]{40,128}")&&port>0&&port<=65535,"Invalid PedalBridge pairing link");}
  public String toString(){return "PedalBridge pairing (private)";}
 }
 static final class Store {
  final SharedPreferences preferences;Pair pair;final String keyName="StadiumPad.PedalBridge.Pairing";
  Store(Context c){preferences=c.getSharedPreferences("PedalBridge",0);try{String encrypted=preferences.getString("pair","");if(!encrypted.isEmpty())pair=new Pair(decrypt(encrypted));}catch(Exception ignored){pair=null;}}
  SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(s.containsAlias(keyName))return (SecretKey)s.getKey(keyName,null);KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(keyName,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}
  String encrypt(String v)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] iv=c.getIV(),body=c.doFinal(v.getBytes(StandardCharsets.UTF_8)),out=new byte[iv.length+body.length];System.arraycopy(iv,0,out,0,iv.length);System.arraycopy(body,0,out,iv.length,body.length);return Base64.getEncoder().encodeToString(out);}
  String decrypt(String v)throws Exception{byte[] b=Base64.getDecoder().decode(v);require(b.length>=29,"Invalid saved pairing");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOf(b,12)));return new String(c.doFinal(Arrays.copyOfRange(b,12,b.length)),StandardCharsets.UTF_8);}
  void configure(String link)throws Exception{Pair p=new Pair(link);preferences.edit().putString("pair",encrypt(link.trim())).apply();pair=p;}
  void forget(){preferences.edit().remove("pair").apply();pair=null;}
 }
 static final class Connection {
  final Pair pair;final InetAddress peer;final String session=UUID.randomUUID().toString(),device,generation,upstream;final boolean matrix;
  Connection(Pair p)throws Exception {pair=p;JSONObject status;try(Socket s=socket(p)){status=authenticate(s,new JSONObject().put("protocol",1).put("token",p.token).put("channel","status"));peer=s.getInetAddress();}require(status.optBoolean("connected"),status.optString("message","PedalBridge is waiting for Stadium"));device=status.getString("device");generation=status.getString("generation");upstream=status.optString("upstream","Network");matrix=status.optBoolean("matrix");require(device.matches("[a-f0-9]{64}")&&!generation.isEmpty(),"Invalid PedalBridge target identity");}
  void matrix(String kind,int output,int source,int field,int value,int channel)throws Exception {require(matrix,"Connect this Stadium to PedalBridge by USB for Matrix control");JSONObject command=new JSONObject().put("kind",kind).put("output",output).put("channel",channel);if(kind.equals("strip")){Matrix.cc(source,field);command.put("source",source).put("field",Matrix.FIELD[field]).put("value",value);}try(Socket socket=socket(pair,peer)){authenticate(socket,new JSONObject().put("protocol",1).put("token",pair.token).put("channel","matrix").put("session",session).put("device",device).put("generation",generation).put("command",command));}}
  Socket open(String channel)throws Exception {Socket s=socket(pair,peer);try{authenticate(s,new JSONObject().put("protocol",1).put("token",pair.token).put("channel",channel).put("session",session).put("device",device).put("generation",generation));return s;}catch(Exception e){s.close();throw e;}}
 }
 static Socket socket(final Pair p)throws Exception{return socket(p,null);}
 static Socket socket(final Pair p,InetAddress peer)throws Exception {SSLContext context=SSLContext.getInstance("TLS");context.init(null,new TrustManager[]{new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[] c,String a)throws CertificateException{try{require(c!=null&&c.length>0&&hash(c[0].getEncoded()).equals(p.pin),"PedalBridge identity changed; pair again");}catch(Exception e){throw new CertificateException("PedalBridge identity changed; pair again");}}}},new SecureRandom());SSLSocket connected=null;List<InetAddress> addresses=new ArrayList<>(peer==null?Arrays.asList(InetAddress.getAllByName(p.host)):Collections.singletonList(peer));addresses.sort(Comparator.comparingInt(address->address instanceof Inet4Address?0:1));IOException unavailable=null;for(InetAddress address:addresses.subList(0,Math.min(4,addresses.size()))){SSLSocket candidate=(SSLSocket)context.getSocketFactory().createSocket();try{candidate.setTcpNoDelay(true);candidate.setSoTimeout(5000);candidate.connect(new InetSocketAddress(address,p.port),2000);connected=candidate;break;}catch(IOException error){unavailable=error;try{candidate.close();}catch(IOException ignored){}}}if(connected==null)throw new IOException("PedalBridge is unavailable on this network. Open it on the Mac and check its connection.",unavailable);SSLSocket s=connected;try{List<String> protocols=new ArrayList<>();for(String v:s.getSupportedProtocols())if(v.equals("TLSv1.2")||v.equals("TLSv1.3"))protocols.add(v);s.setEnabledProtocols(protocols.toArray(new String[0]));s.startHandshake();return s;}catch(Exception e){s.close();throw e;}}
 static JSONObject authenticate(Socket s,JSONObject body)throws Exception {byte[] b=(body.toString()+"\n").getBytes(StandardCharsets.UTF_8);require(b.length<=8192,"Bridge request too large");s.getOutputStream().write(b);s.getOutputStream().flush();ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=s.getInputStream();while(out.size()<8192){int v=in.read();require(v>=0,"PedalBridge disconnected");if(v==10){JSONObject r=new JSONObject(out.toString("UTF-8"));require(r.optBoolean("ok"),r.optString("error","PedalBridge refused connection"));return r;}out.write(v);}throw new IOException("Bridge reply too large");}
 static Network directNetwork(Context c,String route)throws Exception {if(!route.equals("usb")&&!route.equals("wifi"))return null;ConnectivityManager cm=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);List<Network> found=new ArrayList<>();for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);if(cap!=null&&cap.hasTransport(route.equals("usb")?NetworkCapabilities.TRANSPORT_ETHERNET:NetworkCapabilities.TRANSPORT_WIFI))found.add(n);}require(found.size()==1,route.equals("usb")?"Connect one Stadium USB/Ethernet network; USB mode never falls back to Wi-Fi":"Connect the tablet to Wi-Fi first");return found.get(0);}
}
